package playground.jvm;
import java.lang.ref.WeakReference; import java.util.*;
public class GcDemo { public static void main(String[] args)throws Exception {Runtime r=Runtime.getRuntime();List<byte[]> kept=new ArrayList<>();byte[] temporary=new byte[5_000_000];WeakReference<byte[]> label=new WeakReference<>(temporary);print(r,"temporary created");temporary=null;System.out.println("strong reference removed: now GC-eligible");for(int i=0;i<8;i++)kept.add(new byte[1_000_000]);System.gc();Thread.sleep(200);print(r,"after allocation + GC request");System.out.println("weak reference still sees temporary? "+(label.get()!=null));System.out.println("reachable kept objects: "+kept.size());}static void print(Runtime r,String label){long used=r.totalMemory()-r.freeMemory();System.out.printf("%s: used heap ~= %.1f MB%n",label,used/1024.0/1024.0);}}
